mapper.select:
select el.id, el.emp_id, e.name as emp_name, el.leave_type, el.begin_date, el.end_date,
       el.reason, el.status, el.approver_id, el.approve_time,
       el.create_time, el.update_time
from emp_leave el
left join emp e on el.emp_id = e.id


        el.emp_id = #{empId}


        and e.name like concat('%', #{name}, '%')


        and el.leave_type = #{leaveType}


        and el.status = #{status}


        and el.begin_date between #{begin} and #{end}


order by el.create_time desc

mapper.update:
update emp_leave
set status = #{status},
    approver_id = #{approverId},
    approve_time = #{approveTime},
    update_time = #{updateTime}
where id = #{id}
